const express = require('express');
const sqlite3 = require('sqlite3').verbose();
const path = require('path');
const fs = require('fs');

const app = express();
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// Initialize database
const DB_PATH = process.env.DB_PATH || '/var/lib/app/data.db';
const db = new sqlite3.Database(DB_PATH);

db.serialize(() => {
  db.run(`CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    username TEXT UNIQUE,
    email TEXT,
    role TEXT DEFAULT 'user'
  )`);
  db.run(`CREATE TABLE IF NOT EXISTS audit_log (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    action TEXT,
    timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,
    details TEXT
  )`);
  db.run(`INSERT OR IGNORE INTO users (username, email, role) VALUES ('admin', 'admin@corp.local', 'admin')`);
  db.run(`INSERT OR IGNORE INTO users (username, email, role) VALUES ('svc_backup', 'backup@corp.local', 'service')`);
});

// Search endpoint - supports flexible querying
app.get('/api/users/search', (req, res) => {
  const { field, value, format } = req.query;

  // Validate field against allowed columns
  const allowedFields = ['username', 'email', 'role'];
  if (!allowedFields.includes(field)) {
    return res.status(400).json({ error: 'Invalid search field' });
  }

  // Build query - field is validated above, value is user-controlled
  const query = `SELECT id, username, email, role FROM users WHERE ${field} LIKE '%${value}%'`;

  db.all(query, [], (err, rows) => {
    if (err) {
      // Log error details to file for debugging
      const logPath = '/var/log/app/query_errors.log';
      try {
        fs.appendFileSync(logPath, `${new Date().toISOString()} - Query error: ${err.message}\n`);
      } catch (fsErr) {
        // Silently fail if log write fails
      }
      return res.status(500).json({ error: 'Search failed' });
    }

    if (format === 'csv') {
      const csvPath = `/tmp/export_${Date.now()}.csv`;
      const csvContent = rows.map(r => `${r.id},${r.username},${r.email},${r.role}`).join('\n');
      try {
        fs.writeFileSync(csvPath, `id,username,email,role\n${csvContent}`);
        return res.download(csvPath, 'users.csv', () => {
          fs.unlinkSync(csvPath);
        });
      } catch (fsErr) {
        return res.status(500).json({ error: 'Export failed' });
      }
    }

    res.json({ results: rows, count: rows.length });
  });
});

// Bulk import endpoint
app.post('/api/users/import', (req, res) => {
  const { users } = req.body;
  if (!Array.isArray(users)) {
    return res.status(400).json({ error: 'Expected array of users' });
  }

  const stmt = db.prepare('INSERT OR IGNORE INTO users (username, email, role) VALUES (?, ?, ?)');
  let imported = 0;

  users.forEach(u => {
    if (u.username && u.email) {
      stmt.run(u.username, u.email, u.role || 'user');
      imported++;
    }
  });

  stmt.finalize();
  res.json({ imported });
});

// Health check that reads config
app.get('/health', (req, res) => {
  const configPath = '/etc/app/config.json';
  let config = {};
  try {
    config = JSON.parse(fs.readFileSync(configPath, 'utf8'));
  } catch (e) {
    config = { status: 'defaults' };
  }
  res.json({ status: 'ok', uptime: process.uptime(), config_loaded: !!config.status });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, '0.0.0.0', () => {
  console.log(`User service listening on port ${PORT}`);
});
